INSERT INTO "articles" ("title", "slug", "dek", "body_html", "format", "status", "category_id", "author_id", "created_by", "published_at", "updated_content_at", "reading_minutes", "featured")
SELECT 'Coupe de France : le week-end où les petits ont mangé les grands', 'coupe-de-france-le-week-end-ou-les-petits-ont-mange-les-grands', 'Les 24 et 25 octobre, le 6e tour a fait trembler la hiérarchie. Des clubs de quartier, des stades de village et des tirs au but à n''en plus finir : la Coupe a encore fait du bruit.', '<p>Il y a des week-ends où la Coupe de France rappelle pourquoi on l''aime. Pas de stars et pas de droits télé : des bénévoles qui tracent les lignes le samedi matin, des tribunes en bord de main courante et des joueurs qui bossent le lundi. Et au bout, des exploits qu''on raconte encore des années plus tard.</p><h2>⭐ Le derby qui fait mal</h2><p>L''exploit du week-end s''est joué en Corse. Samedi soir, à Armand-Cesari, le SC Bastia (Ligue 3) est tombé face à son voisin Furiani-Agliani (N1), 1-0. Le but est signé Christophe Vincent, un ancien du Sporting. Bastia est le seul club de Ligue 3 éliminé à ce tour.</p><h2>⭐ Les Régionaux ne tremblent pas</h2><p>Le National 1 a pris cher, et souvent au bout du suspense :</p><ul><li>⭐ Plabennec (R1) sort le Stade Briochin (N1) : 1-1, 4-3 aux tirs au but</li><li>⭐ Saint-Sébastien (R1) élimine Saumur (N1) : 2-2, 4-2 aux tirs au but</li><li>⭐ FCOSK Strasbourg (R1) fait tomber Haguenau (N1) : 0-0, 5-3 aux tirs au but</li><li>⭐ Stade Castelbourgeois (R1) renverse Locminé (N1) : 1-1, 4-3 aux tirs au but</li><li>⭐ IC Croix (N2) sort Feignies-Aulnoye (N1) : 2-2, 3-2 aux tirs au but</li><li>⭐ Riviera FC (N2) élimine Istres (N1) : 1-1, 8-7 aux tirs au but</li></ul><p>Le National 2 a encore plus souffert :</p><ul><li>⭐ Senlis (R2) bat Saint-Amand : 1-1, 5-4 aux tirs au but</li><li>⭐ Paray (R2) bat le Jura Dolois : 1-0</li><li>⭐ Contres (R2) bat Vierzon : 1-0</li><li>⭐ Stade Bordelais (R1) balaie Mérignac-Arlac : 4-1</li><li>⭐ Boulazac (R1) bat le Bassin d''Arcachon : 1-0</li></ul><p>Mention spéciale à l''AS Verson (R3), qui a dominé La Ferté-Bagnoles (R1) 4-0.</p><h2>⭐ En Île-de-France, Drancy tombe à Crosne</h2><p>Le coup de tonnerre francilien est venu de l''Essonne. Val d''Yerres Crosne (R2) a éliminé la JA Drancy (N2) au terme d''un match fou, 4-3. Deux divisions d''écart, sept buts, et un club de R2 au 7e tour.</p><p>Autre belle histoire : Maisons-Alfort (R3), plus petit qualifié de la région, a passé six buts à Vélizy (6-2).</p><p>Le reste du tableau francilien :</p><ul><li>Saint-Denis United 1-3 Versailles</li><li>Cergy-Pontoise 1-3 Fleury 91</li><li>Brétigny 0-1 Paris 13 Atletico</li><li>Poissy 2-3 Saint-Ouen-l''Aumône</li><li>Linas-Montlhéry 5-2 Longjumeau</li><li>Tremblay 2-1 CA Vitry</li><li>Clamart 0-1 Les Ulis</li><li>Chatou 0-0 VGA Saint-Maur (5-3 aux tirs au but)</li><li>Trappes – Racing Club de France : reporté au 1er novembre</li></ul><h2>Et maintenant ?</h2><p>Le tirage des 7e et 8e tours aura lieu mercredi 28 octobre à Roland-Garros, à 10h30. Les clubs de Ligue 2 entrent en piste les 14 et 15 novembre. Pour nos petits poucets, le rêve continue, avec peut-être un pro au bout. ⚽</p>', 'article', 'published',
  (SELECT "id" FROM "categories" WHERE "slug" = 'football-amateur'),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
  (SELECT "id" FROM "users" ORDER BY "id" LIMIT 1),
  now(), now(), 2, false
ON CONFLICT ("slug") DO NOTHING;
